package forth

import (
	"fmt"
	"strconv"
	"strings"
)

// op is a single Forth operation. It takes the current data stack and returns
// the updated stack, or an error if the operation cannot be performed.
type op func(stack []int) ([]int, error)

// Forth evaluates the given Forth source lines and returns the resulting data
// stack.
func Forth(input []string) ([]int, error) {
	stack := []int{}
	words := builtins()

	for _, line := range input {
		tokens := strings.Fields(line)
		for i := 0; i < len(tokens); {
			lower := strings.ToLower(tokens[i])
			if lower == ":" {
				next, err := define(tokens, i, words)
				if err != nil {
					return nil, err
				}
				i = next
				continue
			}
			if n, ok := toInt(tokens[i]); ok {
				stack = append(stack, n)
			} else if w, ok := words[lower]; ok {
				stack, err = w(stack)
				if err != nil {
					return nil, err
				}
			} else {
				return nil, fmt.Errorf("undefined operation: %s", tokens[i])
			}
			i++
		}
	}
	return stack, nil
}

// define parses a word definition of the form ": name body ;" starting at the
// ":" token (tokens[start]). It compiles the body against the current word
// table and registers the new word. It returns the index of the first token
// after the closing ";".
func define(tokens []string, start int, words map[string]op) (int, error) {
	if start+1 >= len(tokens) {
		return start, fmt.Errorf("incomplete word definition")
	}
	name := strings.ToLower(tokens[start+1])
	if _, isNum := toInt(tokens[start+1]); isNum {
		return start, fmt.Errorf("cannot redefine a number: %s", tokens[start+1])
	}
	j := start + 2
	var body []string
	for j < len(tokens) && strings.ToLower(tokens[j]) != ";" {
		body = append(body, tokens[j])
		j++
	}
	if j >= len(tokens) {
		return start, fmt.Errorf("unterminated word definition")
	}
	words[name] = compile(body, words)
	return j + 1, nil
}

// compile resolves each token in body against the current word table, capturing
// the meaning of every word at definition time. The returned op applies the
// resolved operations in order.
func compile(body []string, words map[string]op) op {
	ops := make([]op, 0, len(body))
	for _, tok := range body {
		lower := strings.ToLower(tok)
		if n, ok := toInt(tok); ok {
			n := n // capture this iteration's value for the closure
			ops = append(ops, func(s []int) ([]int, error) {
				return append(s, n), nil
			})
			continue
		}
		if w, ok := words[lower]; ok {
			ops = append(ops, w)
			continue
		}
		// Unknown word: keep it, but fail if it is ever executed.
		ops = append(ops, func(s []int) ([]int, error) {
			return nil, fmt.Errorf("undefined operation: %s", tok)
		})
	}
	return func(s []int) ([]int, error) {
		for _, o := range ops {
			var err error
			s, err = o(s)
			if err != nil {
				return nil, err
			}
		}
		return s, nil
	}
}

// toInt reports whether tok is an integer (optionally signed) and returns its
// value.
func toInt(tok string) (int, bool) {
	n, err := strconv.Atoi(tok)
	return n, err == nil
}

// builtins returns the table of built-in words.
func builtins() map[string]op {
	return map[string]op{
		"+":    binary(func(a, b int) int { return a + b }),
		"-":    binary(func(a, b int) int { return a - b }),
		"*":    binary(func(a, b int) int { return a * b }),
		"/":    divide,
		"dup":  dup,
		"drop": drop,
		"swap": swap,
		"over": over,
	}
}

// binary pops two values and pushes f(a, b), where a is the second-from-top and
// b is the top of the stack.
func binary(f func(a, b int) int) op {
	return func(s []int) ([]int, error) {
		if len(s) < 2 {
			return nil, fmt.Errorf("stack underflow")
		}
		b := s[len(s)-1]
		a := s[len(s)-2]
		s = s[:len(s)-2]
		return append(s, f(a, b)), nil
	}
}

func divide(s []int) ([]int, error) {
	if len(s) < 2 {
		return nil, fmt.Errorf("stack underflow")
	}
	b := s[len(s)-1]
	a := s[len(s)-2]
	if b == 0 {
		return nil, fmt.Errorf("divide by zero")
	}
	s = s[:len(s)-2]
	return append(s, a/b), nil
}

func dup(s []int) ([]int, error) {
	if len(s) < 1 {
		return nil, fmt.Errorf("stack underflow")
	}
	return append(s, s[len(s)-1]), nil
}

func drop(s []int) ([]int, error) {
	if len(s) < 1 {
		return nil, fmt.Errorf("stack underflow")
	}
	return s[:len(s)-1], nil
}

func swap(s []int) ([]int, error) {
	if len(s) < 2 {
		return nil, fmt.Errorf("stack underflow")
	}
	s[len(s)-1], s[len(s)-2] = s[len(s)-2], s[len(s)-1]
	return s, nil
}

func over(s []int) ([]int, error) {
	if len(s) < 2 {
		return nil, fmt.Errorf("stack underflow")
	}
	return append(s, s[len(s)-2]), nil
}

